const express = require('express');
const fs = require('fs');
const path = require('path');
const { pipeline, Transform } = require('stream');
const { Asset } = require('../models/asset');

const app = express();

class AssetWatermarkTransform extends Transform {
  constructor(badgeText) {
    super();
    this.badgeHeader = Buffer.from(`<!-- BADGE:${badgeText} -->\n`);
    this.headerWritten = false;
  }

  _transform(chunk, encoding, callback) {
    if (!this.headerWritten) {
      this.push(this.badgeHeader);
      this.headerWritten = true;
    }
    this.push(chunk);
    callback();
  }
}

app.get('/workspace/assets/:assetId/transform', async (req, res) => {
  if (!req.user || !req.user.workspaceId) {
    return res.status(401).send('Authentication required');
  }

  // Verify asset belongs to the caller's active workspace
  const asset = await Asset.findOne({
    where: {
      id: req.params.assetId,
      workspaceId: req.user.workspaceId
    }
  });

  if (!asset) {
    return res.status(403).send('Access denied to requested asset');
  }

  const assetPath = path.join('/var/media/assets', `${req.params.assetId}.svg`);
  if (!fs.existsSync(assetPath)) {
    return res.status(404).send('Asset not found');
  }

  res.setHeader('Content-Type', 'image/svg+xml');
  const readStream = fs.createReadStream(assetPath);
  const transformStream = new AssetWatermarkTransform('WORKSPACE_VERIFIED');

  pipeline(readStream, transformStream, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).send('Transformation stream failed');
    }
  });
});

app.listen(4040);
